-- Copia de solo lectura de las 20 localidades de Bogotá (DD 5.18, P-09). El INSERT es el mismo de la migración V3 de
-- Matching Service (quickpatch-matching, V3__localities_coverage_zones.sql): si la capa oficial cambia, se actualizan las
-- dos migraciones a la vez.

-- Las 20 localidades de Bogotá D.C. (R6). Polígonos de la capa oficial "Localidad" de la Secretaría Distrital de
-- Planeación (Mapa de Referencia IDECA, servicio ordenamientoterritorial/localidad, EPSG 4326), generalizados en
-- el servidor con una tolerancia de 0,0002° (unos 22 m) y 6 decimales. ST_MakeValid corrige los anillos que la
-- generalización pudiera dejar inválidos.
INSERT INTO localities (code, name, area)
SELECT code, name, ST_Multi(ST_CollectionExtract(ST_MakeValid(ST_SetSRID(ST_GeomFromGeoJSON(geojson), 4326)), 3))
